    await ui.refresh(pg_wes);
    expect(await ui.delegate(pg_wes, {"user": "vic", "from": "2026-02-25", "to": "2026-03-15"})).toBe(true);
    await ui.refresh(pg_vic);
    const c_ben_1 = (await ui.addClaim(pg_vic, p_ben, {"amount": "7.77", "date": "2026-03-15"}));
    const t = await pg_vic.locator('[data-testid=claim-form-error]').allTextContents();
    console.log('ERR', JSON.stringify(t));
    await pg_vic.waitForTimeout(1000);
    console.log('ERR2', JSON.stringify(await pg_vic.locator('[data-testid=claim-form-error]').allTextContents()));
  });

